public class SyncCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            SyncCounter c = new SyncCounter();
            check("new counter starts at 0", 0, c.value());
            c.increment();
            c.increment();
            c.increment();
            check("value after 3 increments", 3, c.value());
            check("hammer(1, 10) single thread", 10, SyncCounter.hammer(1, 10));
            check("hammer(8, 1000) loses nothing", 8000, SyncCounter.hammer(8, 1000));
            check("hammer(4, 2500) loses nothing", 10000, SyncCounter.hammer(4, 2500));
            check("hammer(8, 0) zero work", 0, SyncCounter.hammer(8, 0));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
